import torch


class OptimizerModule:
    """Base class for modular optimizer steps.

    Each instance owns a *private* state dictionary.  The previous class-level
    ``state = {}`` made distinct composed modules share the same buffers (two
    MomentumStep instances wrote into one velocity tensor), so the result of a
    composition depended on which instance object was reused instead of on the
    order in which updates were applied.  That breaks the associativity
    requirement

        ((A . B) . C)(p) == (A . (B . C))(p)

    Per-instance state plus a functional (non-aliasing) update makes the
    composition depend only on the application order, hence associative.
    """

    def __init__(self):
        # Per-instance state, keyed by parameter identity.
        self.state = {}

    def _get_state(self, key, like):
        if key not in self.state:
            self.state[key] = torch.zeros_like(like)
        return self.state[key]

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        raise NotImplementedError

    def __call__(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        return self.update(p, grad)

    def __or__(self, other):
        return Compose(self, other)


class Compose(OptimizerModule):
    """Sequential composition of two optimizer modules.

    ``Compose(a, b).update(p, g)`` applies ``b`` first and then ``a``, i.e. the
    mathematical composition ``a . b``.  Since every module keeps its own state
    and no module mutates a tensor owned by another module, grouping (which
    parenthesisation is used) has no effect on the result.
    """

    def __init__(self, first, second):
        super().__init__()
        self.first = first
        self.second = second

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        inner = self.second.update(p, grad)
        return self.first.update(p, inner)


class MomentumStep(OptimizerModule):
    def __init__(self, beta=0.9):
        super().__init__()
        self.beta = beta

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        # State tracking keyed by parameter ID, stored on *this* instance.
        key = id(p)
        v = self._get_state(key, grad)
        # Write into a fresh tensor instead of mutating the state buffer in
        # place: the returned value flows into downstream modules, and
        # aliasing the internal state would leak accidental updates.
        new_v = v.mul(self.beta).add_(grad, alpha=1.0 - self.beta)
        self.state[key] = new_v
        return new_v

