import torch


class OptimizerModule:
    """Base class for composable optimizer modules.

    Each instance owns a private per-parameter state dictionary.  A previous
    version used a *class*-level ``state`` dict, which made every instance
    (and therefore every branch of a nested composition) share the same
    momentum buffer.  With independent per-instance state, composing modules
    is plain function composition, which is strictly associative:

        ((A o B) o C)(p) == (A o (B o C))(p)
    """

    def __init__(self):
        # Instance-level state: composed instances must never collide.
        self.state = {}

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        raise NotImplementedError

    def __call__(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        return self.update(p, grad)

    def compose(self, other: "OptimizerModule") -> "Compose":
        """Return ``self`` followed by ``other``."""
        return Compose(self, other)


class Compose(OptimizerModule):
    """Left-to-right composition of optimizer modules.

    ``Compose(a, b, c)(p, g)`` applies ``a`` to ``g``, then ``b`` to the
    result, then ``c``.  The output of one module is simply threaded into the
    next, so nesting is associative regardless of how modules are grouped.
    """

    def __init__(self, *modules):
        super().__init__()
        self.modules = tuple(modules)

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        out = grad
        for module in self.modules:
            out = module.update(p, out)
        return out


class MomentumStep(OptimizerModule):
    def __init__(self, beta=0.9):
        super().__init__()
        self.beta = beta

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        """Biased momentum update: ``v <- beta * v + (1 - beta) * grad``.

        A fresh tensor is returned rather than the internal buffer so that a
        downstream module may freely mutate its input without corrupting this
        module's hidden state (which would otherwise break associativity of
        nested compositions).
        """
        param_id = id(p)
        entry = self.state.get(param_id)

        # Guard against id() reuse: if the parameter that owned this slot was
        # garbage collected and a different tensor now reuses the address,
        # start a fresh buffer instead of continuing the old momentum.
        if entry is not None:
            buffer, ref = entry
            if ref() is not p:
                entry = None

        if entry is None:
            buffer = torch.zeros_like(grad)
            self.state[param_id] = (buffer, weakref.ref(p))

        buffer.mul_(self.beta).add_(grad, alpha=1.0 - self.beta)
        return buffer.clone()

