import torch


class OptimizerModule:
    """Base class for modular optimizer steps.

    Each instance owns its own private state dictionary, so composed
    instances never share buffers.  ``update`` is a pure function of the
    instance state and its inputs, which makes sequential composition
    strictly associative: ((A o B) o C)(p) == (A o (B o C))(p).
    """

    def __init__(self):
        # Instance-level state: no class-level sharing between modules.
        self.state = {}

    def _get_state(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        """Return the per-parameter buffer for this module, creating it if needed."""
        param_id = id(p)
        buf = self.state.get(param_id)
        if buf is None or buf.shape != grad.shape or buf.dtype != grad.dtype:
            buf = torch.zeros_like(grad)
            self.state[param_id] = buf
        return buf

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        raise NotImplementedError

    def __call__(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        return self.update(p, grad)


class MomentumStep(OptimizerModule):
    """Standard (exponential) moving-average momentum update."""

    def __init__(self, beta=0.9):
        super().__init__()
        self.beta = beta

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        v = self._get_state(p, grad)
        v.mul_(self.beta).add_(grad, alpha=1.0 - self.beta)
        return v


class Compose(OptimizerModule):
    """Sequential composition of optimizer modules.

    Modules are kept in a flattened list, so nested compositions all reduce
    to the same sequence: Compose(Compose(A, B), C) and Compose(A, Compose(B, C))
    both become [A, B, C].  Composition is therefore strictly associative.
    """

    def __init__(self, *modules):
        super().__init__()
        flat = []
        for m in modules:
            if isinstance(m, Compose):
                flat.extend(m.modules)
            else:
                flat.append(m)
        self.modules = flat

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        out = grad
        for m in self.modules:
            out = m.update(p, out)
        return out

