import torch


class OptimizerModule:
    """Base class for modular optimizer update steps.

    Each module keeps its own (per-instance) state.  Buffer state must never be
    stored on the class: a class level dict is shared by every instance, which
    makes the branches of a composition
    ((A o B) o C) and (A o (B o C)) collide on the same buffers, so the two
    parenthesizations diverge after the first step.
    """

    def __init__(self):
        # Instance level state: every module instance owns its own buffers.
        self.state = {}

    def _get_buffer(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        """Return (creating if necessary) the state buffer for ``p``."""
        param_id = id(p)
        buffer = self.state.get(param_id)
        if buffer is None:
            buffer = torch.zeros_like(grad)
            # Keep a reference to the parameter together with the buffer so a
            # parameter cannot be garbage collected and its id reused by a
            # different tensor (which would alias two unrelated buffers).
            self.state[param_id] = buffer
            self.state.setdefault("__refs__", {})[param_id] = p
        elif buffer.shape != grad.shape:
            # The parameter changed shape (e.g. a resized model); re-allocate.
            buffer = torch.zeros_like(grad)
            self.state[param_id] = buffer
            self.state["__refs__"][param_id] = p
        return buffer

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        """Identity update by default: return the gradient unchanged."""
        return grad

    def zero_state(self) -> None:
        """Clear all accumulated state."""
        self.state = {}


class Compose(OptimizerModule):
    """Sequential composition of optimizer modules.

    ``Compose(A, B).update(p, g)`` applies ``B`` first and then ``A``, i.e.
    ``(A o B)(p) = A(B(p))``.  Nested compositions are flattened at
    construction time, so ``((A o B) o C)`` and ``(A o (B o C))`` build the
    exact same flat pipeline, which makes composition associative by
    construction (in addition to each module owning private state).
    """

    def __init__(self, *modules):
        super().__init__()
        flat = []
        for module in modules:
            if isinstance(module, Compose):
                # Flatten one level so both parenthesizations coincide.
                flat.extend(module.modules)
            else:
                flat.append(module)
        self.modules = flat

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        for module in reversed(self.modules):
            grad = module.update(p, grad)
        return grad

    def zero_state(self) -> None:
        for module in self.modules:
            module.zero_state()
        super().zero_state()


def compose(*modules) -> Compose:
    """Right-associative helper: ``compose(A, B, C) == A o (B o C)``."""
    if len(modules) == 1:
        return modules[0] if isinstance(modules[0], Compose) else Compose(modules[0])
    return Compose(modules[0], compose(*modules[1:]))


class MomentumStep(OptimizerModule):
    """Standard (heavy-ball) momentum step.

    ``v <- beta * v + (1 - beta) * g`` and returns ``v``.
    """

    def __init__(self, beta=0.9):
        super().__init__()
        self.beta = beta

    def update(self, p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        v = self._get_buffer(p, grad)
        # Do not mutate the incoming gradient; accumulate into v in place.
        v.mul_(self.beta).add_(grad, alpha=1.0 - self.beta)
        return v

