def compose(*modules):
    """Right-to-left composition: compose(a, b)(p, g) == a(p, b(p, g)).

    Composition stays associative because every module only mutates its own
    per-instance state and hands a fresh value to the next module.
    """
    def fn(p: torch.Tensor, grad: torch.Tensor) -> torch.Tensor:
        for module in reversed(modules):
            grad = module(p, grad)
        return grad

    return fn


